INSERT INTO collection_pages VALUES('eb3e0b28b993dc5587c3a8c9a855333e76b2dae51545c95dab0765766ad9a49b','56ead92c7d731633898b175d4b1bf876fc0e9cc1bc9b5898455f01cf2ef565b3','{"hasNext":false,"items":[{"author":{"account":{"login":"christianprimero926","providerType":"User"},"email":"cospina@vortexbird.com","name":"Christian David Ospina Primero"},"authoredDate":"2026-08-21T19:56:55Z","committedDate":"2026-08-21T19:56:55Z","committer":{"account":{"login":"christianprimero926","providerType":"User"},"email":"cospina@vortexbird.com","name":"Christian David Ospina Primero"},"observedAt":"2026-10-09T00:19:01.515Z","repositoryId":1342177143,"sha":"ec9f242266db015be54d2786fd7596974bf641f5"}],"observedAt":"2026-10-09T00:19:01.515Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/19365676?v=4","events_url":"https://api.github.com/users/christianprimero926/events{/privacy}","followers_url":"https://api.github.com/users/christianprimero926/followers","following_url":"https://api.github.com/users/christianprimero926/following{/other_user}","gists_url":"https://api.github.com/users/christianprimero926/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/christianprimero926","id":19365676,"login":"christianprimero926","node_id":"MDQ6VXNlcjE5MzY1Njc2","organizations_url":"https://api.github.com/users/christianprimero926/orgs","received_events_url":"https://api.github.com/users/christianprimero926/received_events","repos_url":"https://api.github.com/users/christianprimero926/repos","site_admin":false,"starred_url":"https://api.github.com/users/christianprimero926/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/christianprimero926/subscriptions","type":"User","url":"https://api.github.com/users/christianprimero926","user_view_type":"public"},"comments_url":"https://api.github.com/repos/christianprimero926/prueba_tecnica_AMM/commits/ec9f242266db015be54d2786fd7596974bf641f5/comments","commit":{"author":{"date":"2026-08-21T19:56:55Z","email":"cospina@vortexbird.com","name":"Christian David Ospina Primero"},"comment_count":0,"committer":{"date":"2026-08-21T19:56:55Z","email":"cospina@vortexbird.com","name":"Christian David Ospina Primero"},"message":"Implementa flujo de aprobaciones de compra con firma digital concatenada y OTP\n\nBackend serverless en AWS (CDK: Lambda, API Gateway, Step Functions,\nDynamoDB, S3) + frontend de micro-frontends con Module Federation\n(host, solicitante-app, aprobador-app, shared).\n\n- Firma encadenada (SHA-256) por aprobador, con endpoint de verificación\n  de integridad de la cadena.\n- OTP de 6 dígitos, expira en 3 minutos.\n- Un rechazo detiene el flujo de inmediato; la 3ra firma genera el PDF\n  de evidencia y completa la solicitud automáticamente.\n- Configuración por .env en backend, infra (CDK) y cada paquete de\n  frontend, con .env.example documentando cada variable.\n- Backend ~98% cobertura, frontend 92-100% (umbral 60% exigido).\n- Documentación: README, contrato de API (docs/CONTRATO_API.md) y\n  spec OpenAPI (docs/openapi.yaml + docs/api-docs.html).","tree":{"sha":"b3f45f2e7d00d7673d0ae0d40149f8761e75932a","url":"https://api.github.com/repos/christianprimero926/prueba_tecnica_AMM/git/trees/b3f45f2e7d00d7673d0ae0d40149f8761e75932a"},"url":"https://api.github.com/repos/christianprimero926/prueba_tecnica_AMM/git/commits/ec9f242266db015be54d2786fd7596974bf641f5","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/19365676?v=4","events_url":"https://api.github.com/users/christianprimero926/events{/privacy}","followers_url":"https://api.github.com/users/christianprimero926/followers","following_url":"https://api.github.com/users/christianprimero926/following{/other_user}","gists_url":"https://api.github.com/users/christianprimero926/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/christianprimero926","id":19365676